package dev.foxfleet.app.screenshots

import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.test.assertIsDisplayed
import androidx.compose.ui.test.junit4.createComposeRule
import androidx.compose.ui.test.onNodeWithContentDescription
import androidx.compose.ui.test.onRoot
import androidx.compose.ui.unit.Density
import com.github.takahirom.roborazzi.captureRoboImage
import dev.foxfleet.app.data.*
import dev.foxfleet.app.ui.FoxfleetTheme
import dev.foxfleet.app.ui.chat.ChatState
import dev.foxfleet.app.ui.components.LocalMediaHost
import dev.foxfleet.app.ui.components.MediaHost
import dev.foxfleet.app.ui.screens.ChatScreen
import okhttp3.OkHttpClient
import org.junit.Assert.assertFalse
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config
import org.robolectric.annotation.GraphicsMode

private val OUT = System.getProperty("foxfleet.shots") ?: "build/outputs/roborazzi"

/** A reply with MEDIA: tags: the tags are gone from the text, and a picture, a video, a voice note and a file are drawn as cards. */
@RunWith(RobolectricTestRunner::class)
@GraphicsMode(GraphicsMode.Mode.NATIVE)
@Config(sdk = [34], qualifiers = "w411dp-h891dp-xxhdpi")
class MediaScreenshotTest {
    @get:Rule val compose = createComposeRule()
    private val atlas = AgentStatus("Atlas", online = true, chatReady = true, managementReady = true, capabilities = Capabilities(images = true, files = true, sessions = true))
    private val now = System.currentTimeMillis()
    private val reply = "Here is the chart and the recording.\nMEDIA:/home/me/.hermes/cache/images/chart.png\nMEDIA:/tmp/demo.mp4\n[[audio_as_voice]]\nMEDIA:/tmp/note.ogg\nMEDIA:/tmp/report.pdf\nAnd one that is gone: MEDIA:/tmp/missing.png"
    private val host = MediaHost(OkHttpClient()) { _, ref ->
        when {
            ref.endsWith("missing.png") -> throw HubApiException(403, "refused")
            ref.endsWith(".png") -> MediaLink("data:image/png;base64,", "image", "chart.png")
            ref.endsWith(".mp4") -> MediaLink("http://hub/api/media/v", "video", "demo.mp4")
            ref.endsWith(".ogg") -> MediaLink("http://hub/api/media/a", "audio", "note.ogg")
            else -> MediaLink("http://hub/api/media/f", "file", "report.pdf")
        }
    }
    private fun shot(name: String, dark: Boolean, w: Int) {
        RuntimeEnvironment.setQualifiers("+w${w}dp-h891dp-xxhdpi")
        compose.mainClock.autoAdvance = false
        val state = ChatState().apply { load(listOf(UiMessage("user", "Send me the chart", ts = now - 60_000), UiMessage("assistant", reply, ts = now - 30_000)), "s9") }
        compose.setContent {
            val d = LocalDensity.current
            CompositionLocalProvider(LocalDensity provides Density(d.density, 1f), LocalMediaHost provides host) {
                FoxfleetTheme(AppPrefs(theme = if (dark) ThemeMode.Dark else ThemeMode.Light)) { Box(Modifier.fillMaxSize()) { ChatScreen(atlas, listOf(atlas), state, emptyList(), { false }, { _, _ -> }, {}, {}, {}, {}, {}, {}) } }
            }
        }
        compose.mainClock.advanceTimeBy(1200)
        compose.mainClock.autoAdvance = true; compose.waitForIdle(); compose.mainClock.autoAdvance = false; compose.mainClock.advanceTimeBy(900)
        compose.onNodeWithContentDescription("Play video demo.mp4").assertIsDisplayed()
        compose.onNodeWithContentDescription("Play voice message").assertIsDisplayed()
        compose.onNodeWithContentDescription("Download report.pdf").assertIsDisplayed()
        assertFalse("tags must not show", compose.onRoot().toString().contains("MEDIA:"))
        compose.onRoot().captureRoboImage("$OUT/$name-${if (dark) "dark" else "light"}.png")
    }
    @Test fun media360Light() = shot("07-media-cards-360dp", false, 360)
    @Test fun media360Dark() = shot("07-media-cards-360dp", true, 360)
    @Test fun media411Light() = shot("07-media-cards-411dp", false, 411)
    @Test fun media411Dark() = shot("07-media-cards-411dp", true, 411)

    private fun reconnecting(name: String, dark: Boolean, w: Int) {
        RuntimeEnvironment.setQualifiers("+w${w}dp-h891dp-xxhdpi")
        compose.mainClock.autoAdvance = false
        val state = ChatState().apply { load(listOf(UiMessage("user", "Tell me everything", ts = now - 60_000)), "s9"); simulateStream("Thinking about it, part 1. Thinking about it, part 2. ", tool = null); reconnecting = true }
        compose.setContent { FoxfleetTheme(AppPrefs(theme = if (dark) ThemeMode.Dark else ThemeMode.Light)) { Box(Modifier.fillMaxSize()) { ChatScreen(atlas, listOf(atlas), state, emptyList(), { false }, { _, _ -> }, {}, {}, {}, {}, {}, {}) } } }
        compose.mainClock.advanceTimeBy(1200)
        compose.onRoot().captureRoboImage("$OUT/$name-${if (dark) "dark" else "light"}.png")
    }
    @Test fun reconnecting360Light() = reconnecting("08-reconnecting-360dp", false, 360)
    @Test fun reconnecting360Dark() = reconnecting("08-reconnecting-360dp", true, 360)
    @Test fun reconnecting411Light() = reconnecting("08-reconnecting-411dp", false, 411)
    @Test fun reconnecting411Dark() = reconnecting("08-reconnecting-411dp", true, 411)
}
